import { Icon } from "@/registry/erbium/ui/icon";

import { ToggleGroup, ToggleGroupItem } from "@/registry/erbium/ui/toggle-group";

const ToggleGroupDemo = () => (
  <ToggleGroup variant="outline">
    <ToggleGroupItem value="bold" aria-label="Toggle bold">
      <Icon name="bold" className="h-4 w-4" />
    </ToggleGroupItem>
    <ToggleGroupItem value="italic" aria-label="Toggle italic">
      <Icon name="italic" className="h-4 w-4" />
    </ToggleGroupItem>
    <ToggleGroupItem value="strikethrough" aria-label="Toggle strikethrough">
      <Icon name="underline" className="h-4 w-4" />
    </ToggleGroupItem>
  </ToggleGroup>
);

export default ToggleGroupDemo;

import Demo from "../examples/toggle-group-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;
